        es: ["juegos", "jugar", "verdad o reto", "que prefieres", "piedra papel tijera", "retos", "muy picante", "invitar a jugar", "dibujo y adivina", "guia de juegos"],
        en: ["games", "play", "truth or dare", "would you rather", "rock paper scissors", "dare", "extra spicy", "invite to play", "draw and guess", "games guide"],
